+++ b/src/main/java/com/networknt/schema/utils/Strings.java
@@ -18,0 +19,3 @@ package com.networknt.schema.utils;
+import java.util.ArrayList;
+import java.util.List;
+
@@ -128,0 +132,40 @@ public final class Strings {
+
+    /**
+     * Split text. Unlike the JDK String split using regex trailing delimiters are
+     * preserved.
+     * 
+     * @param text the text to split
+     * @param delimiter the delimiter
+     * @return the fragments
+     */
+    public static String[] split(String text, char delimiter) {
+        if (text == null) {
+            return new String[0];
+        }
+        if (text.isEmpty()) {
+            return new String[]{""};
+        }
+
+        List<String> segments = new ArrayList<>();
+        int start = 0;
+        int end;
+
+        while (start <= text.length()) {
+            end = text.indexOf(delimiter, start);
+
+            if (end == -1) {
+                end = text.length();
+            }
+
+            String segment = text.substring(start, end);
+            segments.add(segment);
+
+            if (end == text.length()) {
+                break;
+            }
+
+            start = end + 1;
+        }
+
+        return segments.toArray(new String[segments.size()]);
+    }
